create or replace function public.whatsapp_subscription_active(p_organization_id uuid) returns boolean language sql security definer set search_path=public as $$ select exists(select 1 from public.whatsapp_subscriptions where organization_id=p_organization_id and provider='green-api' and status='active' and starts_at<=now() and ends_at>now()); $$;
revoke all on function public.whatsapp_subscription_active(uuid) from public; grant execute on function public.whatsapp_subscription_active(uuid) to authenticated;
create or replace function public.whatsapp_subscription_mark_expired() returns integer language plpgsql security definer set search_path=public as $$ declare n integer; begin update public.whatsapp_subscriptions set status='expired',updated_at=now() where status='active' and ends_at<=now(); get diagnostics n=row_count; return n; end; $$;
revoke all on function public.whatsapp_subscription_mark_expired() from public; grant execute on function public.whatsapp_subscription_mark_expired() to service_role;
create or replace function public.conik_subscription_mark_expired() returns integer language plpgsql security definer set search_path=public as $$ declare n integer; begin update public.conik_subscriptions set status='expired',updated_at=now() where status='active' and ends_at<=now(); get diagnostics n=row_count; return n; end; $$;
revoke all on function public.conik_subscription_mark_expired() from public; grant execute on function public.conik_subscription_mark_expired() to service_role;
